// ST RM0008/RM0368/RM0383 legacy I2C1, standard/fast-mode 7-bit master with native DMA requests.
// Shift/data registers are bounded; bus traffic consists of physical OD edges.
export class STMI2C1 {
 constructor(runtime){this.r=runtime;this.base=0x40005400;this.reset();}
 reset(){this.regs=new Map([[0,0],[4,0],[8,0],[12,0],[28,0],[32,2]]);this.sr1=0;this.sr2=0;this.seen=0;this.dr=0;this.tx=null;this.rx=[];this.queue=[];this.done=null;this.next=Infinity;this.scl=true;this.sda=true;this.direction=false;this.receiving=false;this.ended=false;this.firstAck=null;this.stopping=false;}
 clocked(){return !!(this.r.regs.get(this.r.board.cpu==='cortex-m4f'?0x40023840:0x4002101c)&(1<<21));}
 enabled(){return this.clocked()&&!!(this.regs.get(0)&1);}
 divider(){const f4=this.r.board.cpu==='cortex-m4f',n=((this.r.regs.get(f4?0x40023808:0x40021004)||0)>>>(f4?10:8))&7;return (n<4?1:1<<(n-3))*(this.r.system?.factor()??1);}
 half(high=false){const c=this.regs.get(28),ticks=(c&4095)*this.divider();return Math.max(1,ticks*(c&32768?(c&16384?(high?9:16):(high?1:2)):1));}
 pins(){const f4=this.r.board.cpu==='cortex-m4f';if(!f4)return this.r.regs.get(0x40010004)&2?{scl:'PB8',sda:'PB9'}:{scl:'PB6',sda:'PB7'};return {scl:['PB6','PB8'].find(p=>this.mapped(p)),sda:['PB7','PB9'].find(p=>this.mapped(p))};}
 mapped(pin){if(!pin||!this.r.board.gpio.includes(pin))return false;const n=+pin.slice(2),f4=this.r.board.cpu==='cortex-m4f';if(f4)return !!(this.r.regs.get(0x40023830)&2)&&((this.r.regs.get(0x40020400)>>>n*2)&3)===2&&!!(this.r.regs.get(0x40020404)&(1<<n))&&((this.r.regs.get(0x40020420+(n>=8?4:0))>>>((n%8)*4))&15)===4;const c=(this.r.regs.get(0x40010c00+(n<8?0:4))>>>((n%8)*4))&15;return !!(this.r.regs.get(0x40021018)&8)&&!!(c&3)&&(c>>>2)===3;}
 refresh(){this.r.circuit?.refresh(true);}
 level(which){const p=this.pins()[which];if(!p)return null;if(!this.r.circuit)return this.r.inputs[p]??null;const v=this.r.inputVoltages[p];return !Number.isFinite(v)?null:v<=.99?false:v>=2.31&&v<=3.6?true:null;}
 schedule(queue,done){if(this.queue.length)throw Error('I²C1 shift register meşgul.');this.queue=queue;this.done=done;this.next=this.r.count+this.half();}
 error(){this.sr1|=256;this.queue=[];this.done=null;this.next=Infinity;this.receiving=false;this.ended=true;}
 tick(){if(!this.enabled()){if(this.queue.length){this.queue=[];this.done=null;this.next=Infinity;this.sr1=0;this.sr2=0;this.rx=[];this.tx=null;this.scl=this.sda=true;this.refresh();}return;}while(this.queue.length&&this.next<=this.r.count){const a=this.queue[0],at=this.next;this.scl=a.scl;this.sda=typeof a.sda==='function'?a.sda():a.sda;this.refresh();if(a.wait&&this.level('scl')!==true){this.next=this.r.count+this.half();return;}if(a.free&&this.level('sda')!==true){this.next=this.r.count+this.half();return;}this.queue.shift();a.sample?.();if(!this.queue.length){const done=this.done;this.done=null;this.next=Infinity;done?.();}else this.next=at+this.half(a.scl);}}
 start(){if(this.queue.length){throw Error('I²C1 START için byte sonunu bekleyin.');}const repeated=!!(this.sr2&1);this.sr1&=~(1|2|4|64|128);this.rx=[];this.tx=null;this.ended=false;this.receiving=false;this.schedule([{scl:false,sda:true}, {scl:true,sda:true,wait:true,free:!repeated},{scl:true,sda:false},{scl:false,sda:false}],()=>{this.regs.set(0,this.regs.get(0)&~256);this.sr1|=1;this.sr2=3;this.seen=0;});}
 stop(){if(this.queue.length||this.sr1&2||this.stopping)return;this.stopping=true;this.receiving=false;this.schedule([{scl:false,sda:false},{scl:true,sda:false,wait:true},{scl:true,sda:true}],()=>{this.sr2=0;this.sr1&=~(1|2|4|128);this.regs.set(0,this.regs.get(0)&~512);this.stopping=false;this.ended=true;});}
 transmit(value,address=false){let ack=false;const q=[];for(let i=7;i>=0;i--){q.push({scl:false,sda:!!(value&(1<<i))},{scl:true,sda:!!(value&(1<<i)),wait:true});}q.push({scl:false,sda:true},{scl:true,sda:true,wait:true,sample:()=>{ack=this.level('sda')===false;}},{scl:false,sda:true});this.schedule(q,()=>{if(!ack){this.sr1|=1024;this.tx=null;this.ended=true;if(this.regs.get(0)&512)this.stop();return;}if(address){this.sr1|=2;this.seen=0;this.direction=!!(value&1);this.sr2=this.direction?3:7;}else{this.sr1|=128;if(this.tx===null)this.sr1|=4;this.pump();}});}
 pump(){if(this.queue.length||this.sr1&2||this.ended)return;if(this.regs.get(0)&512){this.stop();return;}if(!this.direction&&this.tx!==null){const v=this.tx;this.tx=null;this.sr1|=128;this.transmit(v);}else if(this.direction&&this.rx.length<2)this.receive();}
 receive(){this.receiving=true;let value=0,ack;const q=[];for(let i=0;i<8;i++)q.push({scl:false,sda:true},{scl:true,sda:true,wait:true,sample:()=>{const high=this.level('sda');if(high===null)this.error();else value=(value<<1)|(high?1:0);}});q.push({scl:false,sda:true,sample:()=>{ack=this.firstAck??!!(this.regs.get(0)&1024);if((this.regs.get(4)&6144)===6144&&this.r.dma?.i2cLast(this))ack=false;this.firstAck=null;this.sda=!ack;this.refresh();}},{scl:true,sda:()=>!ack,wait:true},{scl:false,sda:true});
  // Resolve the ACK level lazily: CR1.ACK may change during reception.
  this.schedule(q,()=>{this.receiving=false;this.rx.push(value&255);this.sr1|=64;if(this.rx.length===2)this.sr1|=4;if(!ack)this.ended=true;if(this.regs.get(0)&512)this.stop();else if(!this.ended)this.pump();});}
 read(a,n){const off=(a&~3)-this.base;if(off<0||off>36)return undefined;if(![0,4,8,12,16,20,24,28,32].includes(off))throw Error('I²C1 register desteklenmiyor.');let v=this.regs.get(off)||0;if(off===20){v=this.sr1;this.seen=this.sr1&3;}if(off===24){v=this.sr2;if((this.seen&2)&&(this.sr1&2)){this.sr1&=~2;this.seen=0;if(this.direction){this.firstAck=this.regs.get(0)&2048?!!(this.regs.get(0)&1024):null;this.receive();}else{this.sr1|=128;this.pump();}}else if(!v&&this.enabled()&&(this.level('scl')===false||this.level('sda')===false))v=2;}if(off===16){v=this.rx.length?this.rx.shift():this.dr;this.dr=v;if(!this.rx.length)this.sr1&=~64;this.sr1&=~4;this.pump();}return n===4?v>>>0:(v>>>((a&3)*8))&(n===1?255:65535);}
 write(a,v,n){const off=(a&~3)-this.base;if(off<0||off>36)return false;if(![0,4,8,12,16,20,24,28,32].includes(off))throw Error('I²C1 register desteklenmiyor.');if(off===16){if(!this.enabled())return true;if((this.sr1&1)&&(this.seen&1)){this.sr1&=~1;this.seen=0;this.transmit(v&255,true);}else if(!this.direction&&!(this.sr1&2)&&this.sr2&1){if(this.tx!==null)throw Error('I²C1 TXE beklenmeli.');this.tx=v&255;this.sr1&=~(128|4);this.pump();}return true;}if(off===20){this.sr1&=v|~0xff00;return true;}if(off===24)return true;if(n!==4){const shift=(a&3)*8,mask=(n===1?255:65535)<<shift;v=((this.regs.get(off)||0)&~mask)|((v<<shift)&mask);}if(off===0){if(v&32768){this.reset();this.regs.set(0,32768);this.refresh();return true;}if(v&~(1|256|512|1024|2048))throw Error('I²C1 yalnız standard/fast-mode 7-bit master ACK/POS destekler.');if(v&1){const p=this.pins(),freq=this.regs.get(4)&63,ccr=this.regs.get(28);if(!this.mapped(p.scl)||!this.mapped(p.sda))throw Error('I²C1 açık drenaj GPIO AF eksik.');const fast=!!(ccr&32768),minimum=fast?4:2,rate=this.r.board.hz/(this.half(false)+this.half(true));if(freq!==this.r.board.hz/this.divider()/1e6||freq<minimum||!(ccr&4095)||!fast&&(ccr&16384)||rate>(fast?400000:100000))throw Error('I²C1 standard/fast-mode saat/FREQ/CCR sınırı geçersiz.');}}
 if(off===4&&v&~(63|256|512|1024|2048|4096))throw Error('I²C1 CR2 ayrılmış bit yazımı.');if(off===8&&v&32768||off===12&&v&1)throw Error('I²C1 10-bit/dual address slave henüz desteklenmiyor.');if((off===28||off===32)&&(this.regs.get(0)&1))throw Error('I²C1 timing ayarı PE=0 gerektirir.');const old=this.regs.get(off)||0;this.regs.set(off,v>>>0);if(off===0){if(!(v&1)){this.queue=[];this.done=null;this.next=Infinity;this.scl=this.sda=true;this.receiving=false;this.sr1=0;this.sr2=0;}else if((v&256)&&!(old&256))this.start();else if((v&512)&&!(old&512))this.stop();}this.refresh();return true;}
 irqMask(){if(!this.enabled())return 0;const cr=this.regs.get(4);return ((cr&512)&&((this.sr1&7)||((cr&1024)&&(this.sr1&192)))?32:0)|((cr&256)&&(this.sr1&0xff00)?64:0);}
 outputs(states){if(this.enabled())for(const [kind,p]of Object.entries(this.pins()))if(this.mapped(p)){const high=this[kind];states[p]={high,outputEnabled:!high,voltage:0,mode:'I2C1_'+kind.toUpperCase()};}return states;}
}
